#!/usr/bin/env bash
# The hero drawn again holding each other weapon (two sheets of twelve frames per weapon), and idle loops
# for the three NPCs. Usage: MK_KEYS="key" tools/weapons.sh [thuong dao chuy phien cung npc]
export MK_MODELS=${MK_MODELS:-"cx/gpt-image-2 cx/gpt-6-sol-image cx/gpt-image-1.5"}
MAN="one wandering martial artist, a lean man about thirty with a short dark beard and long black hair tied back: wide conical woven bamboo hat, tattered dark indigo knee-length robe with a grey sash, loose charcoal-grey trousers, black cloth boots, a long vermilion red scarf"
S="Style: traditional Chinese ink wash painting (sumi-e) 2D game animation sprite sheet, bold expressive black brush outlines, muted desaturated colours with the vermilion scarf as the only bright accent, cloth shaded in 3 to 4 tones. Every frame shows the SAME character with identical face, costume, colours, proportions and size, full body, side-on three-quarter view facing RIGHT, strong exaggerated line of action, scarf, hair and robe trailing to show motion. Frames laid out in an even grid with wide gaps, never touching or overlapping. The whole sheet has a perfectly plain flat pure white #FFFFFF background, evenly lit like a scanned model sheet, every figure closed by a continuous black outline, no ground, no shadow, no glow, no vignette, no text, no numbers, no frame borders, no speed lines, no slash effects."
good() { [ -s "$1" ] && python tools/white.py "$1"; }
one() {
  for try in 1 2 3 4 5; do
    if good gen/raw_$1.png; then echo "$1 ok"; return; fi
    [ $try = 5 ] && { echo "$1 still bad"; return; }
    echo "$1 try $try"; tools/gen.sh "$1" "$2" "$S"; sleep 2
  done
}
want() { [ ${#ARGS[@]} -eq 0 ] && return 0; for n in "${ARGS[@]}"; do [ "$n" = "$1" ] && return 0; done; return 1; }
ARGS=("$@")
# weapon <id> <what he holds> <how he carries it running> <eight attack frames>
weapon() {
  want $1 || return
  local H="$MAN, $2. He carries no other weapon"
  one w_$1_move "SPRITE SHEET of $H. Twelve frames in three rows of four. Row 1, RUN CYCLE part one, sprinting right leaning far forward, $3: 1 right foot reaching far forward about to land, 2 weight sinking on the bent right leg, 3 pushing off the right leg with the left knee driving forward, 4 airborne with both feet off the ground. Row 2, RUN CYCLE part two: 5 left foot reaching far forward about to land, 6 weight sinking on the bent left leg, 7 pushing off the left leg with the right knee driving forward, 8 airborne with both feet off the ground. Row 3, IDLE BREATHING standing relaxed: 9 neutral, 10 inhaling with shoulders rising and scarf lifting slightly, 11 fully inhaled standing tallest, 12 exhaling with shoulders sinking and knees soft."
  one w_$1_atk "SPRITE SHEET of $H. Twelve frames in three rows of four. $4 Row 3, ACTION POSES: 9 standing guard stance blocking with the weapon held in front of the body, 10 hit recoil staggering backwards with the head thrown back, 11 low horizontal dash with the body almost flat and the scarf streaming, 12 gathering inner force standing with the weapon raised before the face and the robe billowing upward."
}
weapon thuong "holding a long spear with a red tassel below the blade in both hands" "the spear held level at the hip pointing forward" "Row 1, SPEAR THRUST: 1 anticipation with the spear pulled far back and the body coiled, 2 thrust in mid-motion stepping forward, 3 thrust fully extended with the body stretched in a long lunge, 4 recovery pulling the spear back. Row 2, SPEAR SWEEP: 5 anticipation with the spear swung back behind the shoulders, 6 wide horizontal sweep in mid-swing with the body spinning, 7 follow-through with the spear across the far side and robe whirling, 8 recovery planting the spear butt on the ground."
weapon dao "holding a pair of short curved sabers, one in each hand" "both sabers trailing low behind him" "Row 1, TWIN SABER FLURRY: 1 anticipation crouched with both sabers crossed at the chest, 2 right saber slashing forward, 3 left saber slashing forward as the right arm swings back, 4 both sabers cutting outward in a cross slash. Row 2, WHIRLING FINISHER: 5 anticipation twisting the torso with both sabers swept to one side, 6 spinning with both sabers extended like a wheel and robe whirling, 7 follow-through low with one saber forward and one behind, 8 recovery rising with sabers lowered."
weapon chuy "holding a huge heavy long-handled iron mace with a round studded head in both hands" "the mace head dragging low behind him" "Row 1, OVERHEAD SMASH: 1 anticipation heaving the mace up behind the shoulder, 2 the mace swinging over the head, 3 the mace smashed down in front with the body bent over it, 4 recovery dragging the mace back up. Row 2, GREAT SWEEP: 5 anticipation with the mace wound far back and the body twisted, 6 a full horizontal swing in mid-spin with the mace head far out, 7 follow-through with the mace slammed into the ground on the far side, 8 recovery standing with the mace resting on the shoulder."
weapon phien "holding a large iron war fan in the right hand" "the closed fan held back at the hip" "Row 1, FAN THROW: 1 anticipation with the closed fan drawn back across the chest, 2 flicking the fan open while the arm whips forward, 3 arm fully extended with the open fan pointing forward, 4 recovery snapping the fan closed. Row 2, FAN SWEEP: 5 anticipation turning the body with the open fan held behind, 6 a wide sweeping cut with the open fan as the body spins and the robe whirls, 7 follow-through with the fan arm flung wide, 8 recovery standing with the open fan before the chest."
weapon cung "holding a long recurve bow in the left hand, with a quiver of arrows on his back" "the bow held low at his side" "Row 1, STANDING SHOT: 1 nocking an arrow on the string with the bow lowered, 2 half draw raising the bow, 3 full draw with the string at the cheek and the bow bent, 4 release with the string hand flung back and the bow arm straight. Row 2, KNEELING SHOT: 5 dropping to one knee while nocking an arrow, 6 full draw on one knee aiming forward, 7 release on one knee with the string hand flung back, 8 rising with the bow lowered."
if want npc; then
  S="Style: traditional Chinese ink wash painting (sumi-e) 2D game animation sprite sheet, bold expressive black brush outlines, muted desaturated colours with one vermilion accent, 3 to 4 tones of shading. Within a row every frame shows the SAME character with identical face, costume, colours, proportions and size, full body, three-quarter front view. Frames laid out in an even grid of three rows of four with wide gaps, never touching or overlapping. The whole sheet has a perfectly plain flat pure white #FFFFFF background, evenly lit like a scanned model sheet, every figure closed by a continuous black outline, no ground, no shadow, no glow, no vignette, no text, no numbers, no frame borders."
  one npc "IDLE ANIMATION SHEET of three ancient Chinese wuxia characters, twelve frames in three rows of four, each row one character in a four-frame idle loop with small changes between frames. Row 1, a travelling merchant standing with a tall wooden pack frame of goods on his back: 1 standing, 2 shifting the weight of the pack with a shrug, 3 raising one hand in greeting, 4 lowering the hand and nodding. Row 2, an old tea master SITTING on the ground beside a small clay stove and teapot: 1 sitting still, 2 lifting the teapot, 3 pouring tea into a cup with a wisp of steam, 4 setting the pot down and raising the cup. Row 3, an old hermit master with a long white beard standing with a gnarled staff: 1 standing still, 2 stroking his beard, 3 beard and sleeves drifting in the wind with eyes closed, 4 tapping the staff lightly."
fi
echo WEAPONS DONE
